#include <stdio.h>

static void print_line(int spaces, int inner_spaces) {
    for (int s = 0; s < spaces; s++) putchar(' ');
    putchar('*');
    if (inner_spaces >= 0) {
        for (int s = 0; s < inner_spaces; s++) putchar(' ');
        putchar('*');
    }
    putchar('\n');
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    for (int i = 1; i <= n; i++) {
        int spaces = n - i;
        int inner = (i == 1) ? -1 : 2 * i - 3;
        print_line(spaces, inner);
    }
    for (int i = n - 1; i >= 1; i--) {
        int spaces = n - i;
        int inner = (i == 1) ? -1 : 2 * i - 3;
        print_line(spaces, inner);
    }
    return 0;
}

