#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int grid[25][25];
    int val = 1;
    int top = 0, bottom = n - 1, left = 0, right = n - 1;

    while (top <= bottom && left <= right) {
        for (int c = left; c <= right; c++) grid[top][c] = val++;
        top++;
        for (int r = top; r <= bottom; r++) grid[r][right] = val++;
        right--;
        if (top <= bottom) {
            for (int c = right; c >= left; c--) grid[bottom][c] = val++;
            bottom--;
        }
        if (left <= right) {
            for (int r = bottom; r >= top; r--) grid[r][left] = val++;
            left++;
        }
    }

    for (int r = 0; r < n; r++) {
        for (int c = 0; c < n; c++) {
            if (c > 0) printf(" ");
            printf("%d", grid[r][c]);
        }
        printf("\n");
    }
    return 0;
}

