int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int c[20][20];
    for (int r = 0; r < n; r++) {
        c[r][0] = 1;
        c[r][r] = 1;
        for (int k = 1; k < r; k++) {
            c[r][k] = c[r - 1][k - 1] + c[r - 1][k];
        }
    }

    for (int r = 0; r < n; r++) {
        for (int s = 0; s < n - 1 - r; s++) putchar(' ');
        for (int k = 0; k <= r; k++) {
            if (k > 0) putchar(' ');
            printf("%d", c[r][k]);
        }
        putchar('\n');
