#include <stdio.h>

int main(void) {
    int R, N;
    if (scanf("%d %d", &R, &N) != 2) return 0;

    int rows[15][128];
    int counts[15] = {0};

    int curr_row = 0;
    int step = 1;

    for (int num = 1; num <= N; num++) {
        rows[curr_row][counts[curr_row]++] = num;
        if (R > 1) {
            if (curr_row == 0) step = 1;
            else if (curr_row == R - 1) step = -1;
            curr_row += step;
        }
    }

    for (int r = 0; r < R; r++) {
        for (int i = 0; i < counts[r]; i++) {
            if (i > 0) putchar(' ');
            printf("%d", rows[r][i]);
        }
        putchar('\n');
    }
    return 0;
}

