#include <stdio.h>

static void print_stars(int spaces, int stars) {
    for (int s = 0; s < spaces; s++) putchar(' ');
    for (int st = 0; st < stars; st++) putchar('*');
    putchar('\n');
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    for (int i = 0; i < n; i++) {
        print_stars(i, 2 * (n - i) - 1);
    }
    for (int i = 1; i < n; i++) {
        print_stars(n - 1 - i, 2 * i + 1);
    }
    return 0;
}

