reference_solution:
#include <stdio.h>
#include <stdbool.h>

#define MAX_PRIMES 1000

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int total_primes = n * (n + 1) / 2;
    int primes[MAX_PRIMES];
    int count = 0;

    for (int num = 2; count < total_primes; num++) {
        bool is_p = true;
        for (int d = 2; d * d <= num; d++) {
            if (num % d == 0) {
                is_p = false;
                break;
            }
        }
        if (is_p) {
            primes[count++] = num;
        }
    }

    int idx = 0;
    for (int r = 1; r <= n; r++) {
        for (int c = 0; c < r; c++) {
            if (c > 0) putchar(' ');
            printf("%d", primes[idx++]);
        }
        putchar('\n');
    }
    return 0;
}

