#include <stdio.h>

static void print_row(int n, int a) {
    int leading_spaces = (n - a) * 2;
    for (int s = 0; s < leading_spaces; s++) putchar(' ');

    if (a == 1) {
        printf("1\n");
        return;
    }

    int first = 1;
    // Wave 1: 1 to a, then down to 1
    for (int v = 1; v <= a; v++) {
        if (!first) putchar(' ');
        printf("%d", v);
        first = 0;
    }
    for (int v = a - 1; v >= 1; v--) {
        putchar(' ');
        printf("%d", v);
    }
    // Wave 2: 2 to a, then down to 1
    for (int v = 2; v <= a; v++) {
        putchar(' ');
        printf("%d", v);
    }
    for (int v = a - 1; v >= 1; v--) {
        putchar(' ');
        printf("%d", v);
    }
    putchar('\n');
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    for (int k = 1; k <= n; k++) {
        print_row(n, k);
    }
    for (int k = n - 1; k >= 1; k--) {
        print_row(n, k);
    }
    return 0;
}
